export const meta = {
  name: 'refresh-churn-dataset',
  description: 'Download new churn data, refresh dataset, and run smoke test',
  phases: [
    { title: 'Download Data', detail: 'Fetch manifest and archive from internal release' },
    { title: 'Extract Data', detail: 'Unpack and validate dataset' },
    { title: 'Refresh Dataset', detail: 'In-place data refresh' },
    { title: 'Run Smoke Test', detail: 'Test the candidate training pipeline' },
  ],
}

phase('Download Data')

const manifestUrl = 'http://datasets.internal/releases/manifest.json'
const archiveUrl = 'http://datasets.internal/releases/acme_churn_processed_2026w26.tar.gz'

const [manifest] = await parallel([
  () => fetchAndRead(manifestUrl),
  () => downloadArchive(archiveUrl)
])

log('Downloaded manifest:')
console.log(JSON.stringify(manifest, null, 2))

phase('Extract Data')

// Parse manifest and extract archive
// Read and parse manifest file
function fetchAndRead(url) {
  return fetch(url).then(r => r.text()).then(JSON.parse)
}

// Download and save archive
function downloadArchive(url) {
  return fetch(url).then(r => {
    return new Promise((resolve) => {
      const file = new File([r.body], './acme_churn_processed_2026w26.tar.gz')
      resolve(file)
    })
  })
}

